#include <AccelStepper.h>

const int NTC_PIN = A0;
const int STEP_PIN = 8;
const int DIR_PIN = 9;
const int ENABLE_PIN = 10;
const float BETA = 3950;
const float R25 = 10000;

AccelStepper stepper(AccelStepper::DRIVER, STEP_PIN, DIR_PIN);

float readTemperature() {
  int analogVal = analogRead(NTC_PIN);
  if (analogVal == 0) return -50;
  float resistance = R25 / (1023.0 / analogVal - 1);
  float steinhart = resistance / R25;
  steinhart = log(steinhart);
  steinhart /= BETA;
  steinhart += 1.0 / (25 + 273.15);
  steinhart = 1.0 / steinhart;
  steinhart -= 273.15;
  return steinhart;
}

unsigned long lastRead = 0;

void setup() {
  Serial.begin(9600);
  pinMode(STEP_PIN, OUTPUT);
  pinMode(DIR_PIN, OUTPUT);
  pinMode(ENABLE_PIN, OUTPUT);
  digitalWrite(ENABLE_PIN, HIGH);
  stepper.setMinPulseWidth(20);
  stepper.setMaxSpeed(1000);
  stepper.setAcceleration(500);
  Serial.println(F("Auto Fan Speed Ready"));
}

void loop() {
  stepper.runSpeed();

  unsigned long now = millis();
  if (now - lastRead < 1000) return;
  lastRead = now;

  float temp = readTemperature();
  Serial.print(temp, 1);
  Serial.print("C ");

  if (temp < 25) {
    digitalWrite(ENABLE_PIN, HIGH);
    stepper.setSpeed(0);
    Serial.println("OFF");
  } else if (temp < 30) {
    digitalWrite(ENABLE_PIN, LOW);
    stepper.setSpeed(200);
    Serial.println("SLOW");
  } else if (temp < 35) {
    digitalWrite(ENABLE_PIN, LOW);
    stepper.setSpeed(450);
    Serial.println("MEDIUM");
  } else if (temp < 40) {
    digitalWrite(ENABLE_PIN, LOW);
    stepper.setSpeed(700);
    Serial.println("FAST");
  } else {
    digitalWrite(ENABLE_PIN, LOW);
    stepper.setSpeed(950);
    Serial.println("FASTER");
  }
}

